{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The block_public_acls setting is omitted and therefore defaults to false, allowing public ACLs to be applied to the referenced bucket."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 public bucket policies are not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The block_public_policy setting is omitted and therefore defaults to false, allowing policies that grant public access to the referenced bucket."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "S3 public ACLs are not ignored",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The ignore_public_acls setting is omitted and therefore defaults to false, so existing public ACL grants may remain effective."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 public bucket access is not restricted",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The restrict_public_buckets setting is explicitly false, permitting public or cross-account access granted by a public bucket policy."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled all four S3 Block Public Access controls for the API documentation bucket."
}
